import crypto from "node:crypto";
import fs from "node:fs";
import net from "node:net";
import dgram from "node:dgram";
import path from "node:path";
import { RtspClient } from "./rtsp-client";
import { buildBplist, parseBplist, type PlistValue } from "../../src/shared/airplay/bplist";
import { MirrorDecryptor } from "../../src/main/airplay/crypto";
import { annexBToAvcc, encodeMirrorPacket, MirrorPayload } from "../../src/shared/airplay/mirror";

/** Synthetic sender against the REAL native receiver. The wrapped-key fixture
 * is generated by fairplay-vector.c, not a fixed-key path in the receiver.
 */
export class NativePhone {
  readonly client = new RtspClient();
  private timing = dgram.createSocket("udp4");
  private data?: net.Socket;
  private secret!: Buffer;
  private encryptor!: MirrorDecryptor;
  private sid = "424242";
  private frameIndex = 0;
  private ptsUs = 0;
  private audioKey!: Buffer;
  private audioPort = 0;
  private audioSocket = dgram.createSocket("udp4");
  private nals: Buffer[];
  readonly frames: Buffer[][] = [];
  constructor() {
    const fixture = fs.readFileSync(path.resolve("test/fixtures/stream.h264"));
    this.nals = fixture.toString("latin1").split(/\x00\x00\x00?\x01/).filter(Boolean).map((n) => Buffer.from(n, "latin1"));
    for (const nal of this.nals.filter((n) => [1, 5].includes(n[0]! & 31))) {
      if (!this.frames.length || (nal[1]! & 0x80)) this.frames.push([]);
      this.frames[this.frames.length - 1]!.push(nal);
    }
  }
  async connect(port: number) {
    await this.client.connect(port);
    const ed = crypto.generateKeyPairSync("ed25519"), x = crypto.generateKeyPairSync("x25519");
    const raw = (key: crypto.KeyObject) => key.export({ type: "spki", format: "der" }).subarray(-32);
    const setup = await this.client.request("POST", "/pair-setup", raw(ed.publicKey));
    const verify = await this.client.request("POST", "/pair-verify", Buffer.concat([Buffer.from([1, 0, 0, 0]), raw(x.publicKey), raw(ed.publicKey)]));
    if (setup.body.length !== 32 || verify.body.length !== 96) throw new Error("Native pairing response is invalid");
    const serverX = verify.body.subarray(0, 32);
    this.secret = crypto.diffieHellman({ privateKey: x.privateKey, publicKey: crypto.createPublicKey({ key: Buffer.concat([Buffer.from("302a300506032b656e032100", "hex"), serverX]), type: "spki", format: "der" }) });
    const derive = (label: string) => crypto.createHash("sha512").update(label).update(this.secret).digest().subarray(0, 16);
    const key = derive("Pair-Verify-AES-Key"), iv = derive("Pair-Verify-AES-IV");
    const decipher = crypto.createDecipheriv("aes-128-ctr", key, iv);
    const sig = decipher.update(verify.body.subarray(32));
    const serverEd = crypto.createPublicKey({ key: Buffer.concat([Buffer.from("302a300506032b6570032100", "hex"), setup.body]), type: "spki", format: "der" });
    if (!crypto.verify(null, Buffer.concat([serverX, raw(x.publicKey)]), serverEd, sig)) throw new Error("Native receiver identity signature is invalid");
    const cipher = crypto.createCipheriv("aes-128-ctr", key, iv);
    cipher.update(Buffer.alloc(64));
    const signature = crypto.sign(null, Buffer.concat([raw(x.publicKey), serverX]), ed.privateKey);
    await this.client.request("POST", "/pair-verify", Buffer.concat([Buffer.alloc(4), cipher.update(signature)]));
    const challenge = Buffer.alloc(16); challenge.write("FPLY"); challenge[4] = 3;
    const fp1 = await this.client.request("POST", "/fp-setup", challenge);
    const handshake = Buffer.alloc(164, 0x42); handshake.write("FPLY"); handshake[4] = 3;
    handshake[12] = 0;
    const fp2 = await this.client.request("POST", "/fp-setup", handshake);
    if (fp1.body.length !== 142 || fp2.body.length !== 32) throw new Error("Native FairPlay handshake failed");
  }
  async start() {
    this.timing.on("message", (packet, remote) => {
      if (packet.length < 32) return;
      const reply = Buffer.alloc(32); reply[0] = 0x80; reply[1] = 0xd3;
      packet.copy(reply, 8, 24, 32);
      const now = (BigInt(Math.floor(Date.now() / 1000)) + 2208988800n) << 32n;
      reply.writeBigUInt64BE(now, 16); reply.writeBigUInt64BE(now, 24);
      this.timing.send(reply, remote.port, remote.address);
    });
    await new Promise<void>((r) => this.timing.bind(0, "127.0.0.1", r));
    await this.client.request("SETUP", "rtsp://localhost/stream", buildBplist({ name: "Native test iPhone", model: "iPhone14,5", deviceID: "00:11:22:33:44:55", ekey: new Uint8Array(Buffer.alloc(72, 0x21)), eiv: new Uint8Array(16), timingPort: this.timing.address().port, timingProtocol: "NTP" }), "application/x-apple-binary-plist");
    const response = await this.client.request("SETUP", "rtsp://localhost/stream", buildBplist({ streams: [{ type: 110, streamConnectionID: BigInt(this.sid) }, { type: 96, ct: 8, spf: 480, usingScreen: true, controlPort: 0, audioFormat: 0x1000000 }] }), "application/x-apple-binary-plist");
    const plist = parseBplist(response.body) as { streams: Record<string, PlistValue>[] };
    const port = Number(plist.streams[0]!.dataPort);
    this.audioPort = Number(plist.streams[1]!.dataPort);
    this.data = net.connect(port, "127.0.0.1");
    this.data.on("error", () => undefined);
    await new Promise<void>((resolve, reject) => { this.data!.once("connect", resolve); this.data!.once("error", reject); });
    const audioKey = crypto.createHash("sha512").update(Buffer.from("5a70c954008d84e33a4638c697e84cb6", "hex")).update(this.secret).digest().subarray(0, 16);
    this.audioKey = audioKey;
    this.encryptor = new MirrorDecryptor(this.sid, audioKey);
    this.frameIndex = 0;
    this.ptsUs = 0;
    this.sendConfig();
  }
  private sendConfig() {
    const sps = this.nals.find((n) => (n[0]! & 31) === 7)!;
    const pps = this.nals.find((n) => (n[0]! & 31) === 8)!;
    const config = Buffer.alloc(11 + sps.length + pps.length);
    config.set([1, sps[1]!, sps[2]!, sps[3]!, 255, 225]);
    config.writeUInt16BE(sps.length, 6); sps.copy(config, 8);
    config[8 + sps.length] = 1;
    config.writeUInt16BE(pps.length, 9 + sps.length); pps.copy(config, 11 + sps.length);
    this.data!.write(encodeMirrorPacket(MirrorPayload.CONFIG, config, { width: 368, height: 640, ntp: 1n << 32n }));
  }
  async stream(count = 40, fps = 30) {
    const started = performance.now();
    for (let i = 0; i < count; i++) {
      const frame = this.frames[i % this.frames.length]!;
      const ntp = (1n << 32n) + BigInt(Math.round(this.ptsUs)) * (1n << 32n) / 1000000n;
      this.frameIndex++; this.ptsUs += 1000000 / fps;
      this.data!.write(encodeMirrorPacket(MirrorPayload.VIDEO, this.encryptor.decrypt(Buffer.from(annexBToAvcc(frame))), { ntp }));
      await new Promise((resolve) => setTimeout(resolve, Math.max(0, started + (i + 1) * 1000 / fps - performance.now())));
    }
  }
  async streamAudio() {
    const fixture = fs.readFileSync(path.resolve("test/fixtures/tone-aac-eld.bin"));
    let offset = 0, seq = 0;
    while (offset < fixture.length) {
      const size = fixture.readUInt32BE(offset); offset += 4;
      const plain = fixture.subarray(offset, offset + size); offset += size;
      const cipher = crypto.createCipheriv("aes-128-cbc", this.audioKey, Buffer.alloc(16)).setAutoPadding(false);
      const encrypted = Buffer.concat([cipher.update(plain.subarray(0, size - size % 16)), cipher.final(), plain.subarray(size - size % 16)]);
      const head = Buffer.alloc(12); head[0] = 128; head[1] = 96;
      head.writeUInt16BE(seq, 2); head.writeUInt32BE(seq++ * 480, 4);
      this.audioSocket.send(Buffer.concat([head, encrypted]), this.audioPort, "127.0.0.1");
      await new Promise((r) => setTimeout(r, 11));
    }
  }
  close() {
    this.data?.destroy();
    this.client.close();
    try { this.timing.close(); } catch { /* not bound */ }
    try { this.audioSocket.close(); } catch { /* not bound */ }
  }
}
